package com.bank.qa.mockstub;

import java.math.BigDecimal;

// Unit under test: depends on FraudCheck (stub) and Notifier (mock).
class TransferService {
    private final FraudCheck fraud;
    private final Notifier notifier;
        TransferService(FraudCheck fraud, Notifier notifier) { this.fraud = fraud;
        this.notifier = notifier; }

    boolean transfer(String from, String to, BigDecimal amount) {
        if (!fraud.isAllowed(from, amount)) {
            return false;                       // blocked: must NOT notify
        }
        // ... move money ...
        notifier.notify(from, "Transferred " + amount + " to " + to); // must notify ONCE
        return true;
    }
}
