package com.bank.qa.mockstub;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class MockStubDemo {
    private static final Logger log = Logger.getLogger(MockStubDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new MsLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // STUB: returns a preset value to CONTROL behavior the code sees.
        FraudCheck allowStub = (acct, amt) -> true;   // "Mockito: when(...).thenReturn(true)"
        FraudCheck blockStub = (acct, amt) -> false;  // control the other branch

        // MOCK: records calls so we can VERIFY interactions.
        List<String> notifyCalls = new ArrayList<>();
        Notifier notifierMock = (acct, msg) -> notifyCalls.add(acct + "|" + msg);

        log.info("=== Stub controls behavior; Mock verifies interaction ===");
        TransferService ok = new TransferService(allowStub, notifierMock);
        boolean result = ok.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info("success transfer returned " + result + " (stub said allowed)");
        // VERIFY: notifier called EXACTLY once (Mockito: verify(notifier, times(1)).notify(...))
        log.info("notifier called " + notifyCalls.size() + " time(s) -> "
            + (notifyCalls.size() == 1 ? "PASS" : "FAIL") + "  " + notifyCalls);

        log.info("=== Blocked transfer must NOT notify ===");
        notifyCalls.clear();
        TransferService blocked = new TransferService(blockStub, notifierMock);
        boolean blockedResult = blocked.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info("blocked transfer returned " + blockedResult + " (stub said NOT allowed)");
        // VERIFY: notifier NEVER called (Mockito: verify(notifier, never()).notify(...))
        log.info("notifier called " + notifyCalls.size() + " time(s) -> "
            + (notifyCalls.isEmpty() ? "PASS (never)" : "FAIL"));

        log.info("HTTP dependency (exchange-rate API) -> use WireMock: stub a fake "
            + "HTTP server returning fixed JSON, errors, or delays deterministically.");
    }
}

// ─── Would be in MsLogFormatter.java in a real project ───
class MsLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
